% ----------------------------- DH 矩阵计算 --------------------------------
function T = dhMatrix(params, theta)
    % params = [a, alpha, d]; theta 为弧度
    C  = cos(theta);
    S  = sin(theta);
    Ca = cos(params(2));
    Sa = sin(params(2));
    a  = params(1);
    d  = params(3);

    T = [
        C,            -S*Ca,          S*Sa,            a*C;
        S,             C*Ca,          -S*Sa,           a*S;
        0,              Sa,              Ca,               d;
        0,              0,                0,               1
    ];
